      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "memory_clean_background",
      "src": "assets/memory-clean-bg.png",
      "use": "background image",
      "description": "内存清理和存储空间主题背景图，适合承载叠加的仪表盘、状态文字和底部日程信息。",
      "bindTo": "/storage/background"
    },
    {
      "assetRef": "memory_clean_icon",
      "src": "assets/memory-clean-icon.png",
      "use": "memory and storage icon",
      "description": "内存清理图标素材，可用于表达内存、存储或系统优化状态。",
      "bindTo": "/device/items/1/icon"
    },
    {
      "assetRef": "electricity_icon",
      "src": "resources/base/media/icon_electricity.png",
      "use": "battery icon",
      "description": "电池图标素材，用于表达电池和电量管理入口。",
      "bindTo": "/device/items/0/icon"
    }
  ]
}

